<parameter name="content">import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (props: FallbackProps) => ReactNode;
}

interface FallbackProps {
  error: Error;
  errorInfo: ErrorInfo;
  retry: () => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    this.setState({ errorInfo });
    console.error("[ErrorBoundary] Uncaught render error:", {
      message: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack,
    });
  }

  private retry = (): void => {
    this.setState({ error: null, errorInfo: null });
  };

  render(): ReactNode {
    const { error, errorInfo } = this.state;

    if (error && errorInfo) {
      if (this.props.fallback) {
        return this.props.fallback({ error, errorInfo, retry: this.retry });
      }
      return <DefaultFallback error={error} errorInfo={errorInfo} retry={this.retry} />;
    }

    return this.props.children;
  }
}

function DefaultFallback({ error, errorInfo, retry }: FallbackProps) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.heading}>Something went wrong</h2>
      <p style={styles.message}>{error.message}</p>
      <details style={styles.details}>
        <summary style={styles.summary}>Component stack</summary>
        <pre style={styles.pre}>{errorInfo.componentStack}</pre>
      </details>
      <button onClick={retry} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    margin: "1rem",
    border: "1px solid #f87171",
    borderRadius: "0.5rem",
