<parameter name="content">import React, { useState } from "react";
import { ErrorBoundary } from "./ErrorBoundary";

// A component that throws on demand — simulates a render crash.
function Bomb({ shouldThrow }: { shouldThrow: boolean }) {
  if (shouldThrow) throw new Error("Simulated render failure");
  return <p>Component rendered successfully.</p>;
}

// Example 1: default fallback UI
export function DefaultFallbackExample() {
  const [boom, setBoom] = useState(false);
  return (
    <ErrorBoundary>
      <button onClick={() => setBoom(true)}>Trigger error</button>
      <Bomb shouldThrow={boom} />
    </ErrorBoundary>
  );
}

// Example 2: custom fallback render prop
export function CustomFallbackExample() {
  const [boom, setBoom] = useState(false);
  return (
    <ErrorBoundary
      fallback={({ error, retry }) => (
        <div style={{ padding: "1rem", background: "#1e1e2e", color: "#cdd6f4", borderRadius: 8 }}>
          <strong>Custom fallback:</strong> {error.message}
          <br />
          <button onClick={retry} style={{ marginTop: 8 }}>
            Retry
          </button>
        </div>
      )}
    >
      <button onClick={() => setBoom(true)}>Trigger error</button>
      <Bomb shouldThrow={boom} />
    </ErrorBoundary>
  );
}
</parameter>
